import { useId, useMemo } from 'react';
import { CONSTELLATIONS } from '../data/constellations';
import './Constellation.css';

function buildLines(nodes, edges) {
  return edges.map(([a, b], index) => {
    const from = nodes[a];
    const to = nodes[b];
    const length = Math.hypot(to.x - from.x, to.y - from.y);
    return { from, to, length, index };
  });
}

export default function Constellation({
  variant = 'pisces',
  active = false,
  showLabel = false,
  className = '',
}) {
  const prefix = useId();
  const data = CONSTELLATIONS[variant];

  const lines = useMemo(
    () => buildLines(data.nodes, data.edges),
    [data.nodes, data.edges]
  );

  if (!data) return null;

  return (
    <svg
      className={`constellation ${active ? 'constellation--active' : ''} ${className}`.trim()}
      viewBox={data.viewBox}
      preserveAspectRatio="xMaxYMin meet"
      aria-hidden={!showLabel}
      role={showLabel ? 'img' : undefined}
      aria-label={showLabel ? `${data.name} constellation` : undefined}
    >
      {lines.map(({ from, to, length, index }) => (
        <line
          key={`${prefix}-line-${index}`}
          className="constellation__line"
          x1={from.x}
          y1={from.y}
          x2={to.x}
          y2={to.y}
          strokeDasharray={length}
          strokeDashoffset={length}
          style={{ '--line-length': length, '--line-delay': `${index * 80}ms` }}
        />
      ))}
      {data.nodes.map((node, i) => (
        <circle
          key={`${prefix}-node-${i}`}
          className="constellation__dot"
          cx={node.x}
          cy={node.y}
          r="2.8"
        />
      ))}
      {showLabel && (
        <text
          x="4"
          y="12"
          className="constellation__label"
        >
          {data.name}
        </text>
      )}
    </svg>
  );
}
